INSERT INTO public.community_deals (slug, title, source_url, image_urls, price_eur, currency, country, location_name, sqm, bedrooms, category, why_great, verified_note, status, is_editorial_pick, pick_note, approved_at, publish_at, verified_at, cover_fixed)
VALUES
('galdar-mountain-cave-99500', 'Canarian cave home with a mountain-facing terrace', 'https://www.thinkspain.com/property-for-sale/9153553', ARRAY['https://cdn.thinkwebcontent.com/property/2271/9153553/20250801210211/w1500h1125/s1600x1200/x-259522291.jpg','https://cdn.thinkwebcontent.com/property/2271/9153553/20250801210208/w1500h1125/s1600x1200/x-259522286.jpg','https://cdn.thinkwebcontent.com/property/2271/9153553/20250801210208/w1500h1125/s1600x1200/x-259522265.jpg','https://cdn.thinkwebcontent.com/property/2271/9153553/20250801210206/w1500h1125/s1600x1200/x-259522275.jpg','https://cdn.thinkwebcontent.com/property/2271/9153553/20250801210200/w1500h1125/s1600x1200/x-259522282.jpg']::text[], 99500, 'EUR', 'Spain', 'Barranco Hondo, Gáldar, Gran Canaria', 81, 2, 'village', 'White cave walls, a planted terrace and rugged mountain views in Barranco Hondo. The advertiser describes a well-maintained, furnished home with two bedrooms and one bathroom, ready to use without renovation. Several rooms open directly onto the terrace. Access is on foot: cars cannot reach the house, and parking is approximately 50 metres away.', 'Asking price and photographs checked against the live advertiser listing on 2 October 2026. Seller confirmation and an on-site inspection are still pending.', 'approved', true, 'Selected for its mountain-facing garden terrace and traditional white cave architecture.', now(), now(), now(), true),
('galera-hillside-cave-84000', 'A white cave house perched above Galera', 'https://www.thinkspain.com/property-for-sale/7107734', ARRAY['https://cdn.thinkwebcontent.com/property/6970/7107734/20260420174257/w800h450/s1600x1200/x-279215476.jpg','https://cdn.thinkwebcontent.com/property/6970/7107734/20260420174255/w800h533/s1600x1200/x-279215482.jpg','https://cdn.thinkwebcontent.com/property/6970/7107734/20260420174300/w800h533/s1600x1200/x-279215485.jpg','https://cdn.thinkwebcontent.com/property/6970/7107734/20260420174306/w800h533/s1600x1200/x-279215488.jpg','https://cdn.thinkwebcontent.com/property/6970/7107734/20260420174309/w800h450/s1600x1200/x-279215501.jpg']::text[], 84000, 'EUR', 'Spain', 'Galera, Granada', NULL, 2, 'village', 'A whitewashed cave home set into the hillside above historic Galera, with a terrace overlooking the village and surrounding countryside. The listing describes two double bedrooms, a fitted kitchen, a living room with fireplace and one bathroom, all in good condition. Parking is nearby. The advertiser does not provide a reliable internal floor area, so none is shown here.', 'Asking price and photographs checked against the live advertiser listing on 2 October 2026. Seller confirmation and an on-site inspection are still pending.', 'approved', true, 'Selected for its striking hillside setting, white facade and village panorama.', now(), now(), now(), true),
('terque-stone-terrace-cave-79500', 'A stone dining terrace above the Andarax valley', 'https://www.thinkspain.com/property-for-sale/9816571', ARRAY['https://cdn.thinkwebcontent.com/property/31088/9816571/20260505165731/w1194h866/s1600x1200/x-280211998.jpg','https://cdn.thinkwebcontent.com/property/31088/9816571/20260509085724/w2048h1152/s1600x1200/x-280512774.jpg','https://cdn.thinkwebcontent.com/property/31088/9816571/20260509085722/w2048h1152/s1600x1200/x-280512772.jpg']::text[], 79500, 'EUR', 'Spain', 'Terque, Almería', 81, 2, 'village', 'A rustic stone terrace with outdoor dining and views towards the Andarax valley is the highlight of this furnished cave home in Terque''s Al-Kamar area. The listing includes two bedrooms, one bathroom and an open living area with a fireplace, and describes it as ready to move into. It is inland, with the coast approximately 30 km away. Interiors retain traditional, modest finishes.', 'Asking price and photographs checked against the live advertiser listing on 2 October 2026. Seller confirmation and an on-site inspection are still pending.', 'approved', true, 'Selected for its sunny stone terrace, mountain outlook and whitewashed exterior.', now(), now(), now(), true),
('caniles-rooftop-mountains-75000', 'A white village home with a Sierra de Baza roof terrace', 'https://www.thinkspain.com/property-for-sale/9860590', ARRAY['https://cdn.thinkwebcontent.com/property/6970/9860590/20260604230818/w987h555/s1600x1200/x-282755317.jpg','https://cdn.thinkwebcontent.com/property/6970/9860590/20260604230822/w987h555/s1600x1200/x-282755318.jpg','https://cdn.thinkwebcontent.com/property/6970/9860590/20260527084631/w987h555/s1600x1200/x-281832373.jpg']::text[], 75000, 'EUR', 'Spain', 'Caniles, Granada', 150, 4, 'village', 'A sunny roof terrace looks across the green valley towards the Sierra de Baza. This two-storey home combines conventional rooms with cave rooms extending through the hillside, with entrances on both sides. The listing describes four bedrooms, three bathrooms, fireplaces and a carport, and says it is ready to move into. Interiors are traditional rather than recently styled. Baza is around 15 minutes away by car.', 'Asking price and photographs checked against the live advertiser listing on 2 October 2026. Seller confirmation and an on-site inspection are still pending.', 'approved', true, 'Selected for its roof terrace, open mountain view and white village facade.', now(), now(), now(), true)
